import json, random, subprocess, sys, collections, copy
sys.path.insert(0,'/workspace/submission')
sys.path.insert(0,'/workspace/tmp')
import main as entry
import topo_test

CONFIGS=[
 ['clos',4,'tor',1],['clos',4,'pod',1],['clos',6,'tor',0],['clos',6,'pod',1],
 ['leaf-spine',2,1],['leaf-spine',4,3],['leaf-spine',7,2],
 ['torus2d',3,'host'],['torus2d',3,'row'],['torus2d',4,'host'],['torus2d',4,'row'],
 ['torus3d',3,'host'],['torus3d',3,'line'],
 ['dragonfly',2,1,1,'router'],['dragonfly',4,1,3,'group'],['dragonfly',5,2,2,'target'],
 ['dragonfly-plus',2,2,2,1,1,'tor'],['dragonfly-plus',3,2,1,2,0,'group'],
 ['dragonfly-plus',4,1,3,1,0,'tor'],['dragonfly-plus',3,1,1,1,1,'group'],
]
# cache topology info by repr
CACHE={}
def toinfo(top):
    k=json.dumps(top)
    if k not in CACHE:CACHE[k]=topo_test.topo(top)
    return CACHE[k]

def stats(tasks,quotas,budgets,caps,n,pairs,dom):
    ng=len(quotas)
    gl=[0]*ng;gp=[set() for _ in range(ng)];gc=[0]*ng;gpin=[0]*ng
    pairsets=[set() for _ in range(ng)]
    for task in tasks:
        t,g,w,c,p=task
        gl[g]+=w;gp[g].update(pairs[t][2]);gc[g]+=1;gpin[g]+=p;pairsets[g].add((dom[t],c))
    usage=[0]*n
    for g in range(ng):
        if gc[g]:
            for node in gp[g]:usage[node]+=quotas[g]
    return gl,gp,gc,gpin,pairsets,usage

def cert(tasks,quotas,budgets,caps,n,pairs,dom,query):
    gl,gp,gc,gpin,pairsets,usage=stats(tasks,quotas,budgets,caps,n,pairs,dom)
    groups=[]
    for g in query['groups']:
        if gc[g]:
            assert len(pairsets[g])==1,(g,pairsets[g])
            d,c=next(iter(pairsets[g]))
        else:d=c=-1
        groups.append([g,gc[g],gl[g],quotas[g],budgets[g],len(gp[g]),d,c])
    nodes=[[x,usage[x],caps[x]] for x in query['nodes']]
    taskrows=[[i,tasks[i][1],tasks[i][0],tasks[i][2],tasks[i][3],tasks[i][4]] for i in query['tasks']]
    return {'totals':[sum(1 for x in gc if x),sum(usage),sum(t[2] for t in tasks),sum(t[4] for t in tasks)],
            'groups':groups,'nodes':nodes,'tasks':taskrows}

def initial_ok(tasks,quotas,budgets,caps,n,pairs,dom):
    gl,gp,gc,gpin,pairsets,usage=stats(tasks,quotas,budgets,caps,n,pairs,dom)
    for g in range(len(quotas)):
        if gc[g]:
            if quotas[g]<=0 or len(pairsets[g])!=1 or gl[g]>quotas[g]*budgets[g]:return False
    return all(usage[i]<=caps[i] for i in range(n))

def gen_seed(seed):
    rnd=random.Random(seed)
    top=rnd.choice(CONFIGS)
    n,pairs,dom=toinfo(top);m=len(pairs)
    ng=rnd.randint(1,5)
    groups=[];tasks=[]
    all_domains=sorted(set(dom))
    empties=0
    for g in range(ng):
        quota=rnd.randint(1,4)
        if rnd.random()<0.2:
            groups.append([quota,rnd.randint(1,20)]);continue
        d=rnd.choice(all_domains); cls=rnd.randint(0,5)
        candidates=[i for i,x in enumerate(dom) if x==d]
        load=0; before=len(tasks)
        for _ in range(rnd.randint(1,5)):
            w=rnd.randint(1,10);load+=w
            tasks.append([rnd.choice(candidates),g,w,cls,rnd.randint(0,1)])
        lo=max(1,(load+quota-1)//quota)
        budget=rnd.randint(lo,max(lo,20))
        groups.append([quota,budget])
    quotas=[x[0] for x in groups];budgets=[x[1] for x in groups]
    _,_,_,_,_,baseusage=stats(tasks,quotas,budgets,[0]*n,n,pairs,dom)
    caps=[baseusage[i]+rnd.randint(0,4) for i in range(n)]
    assert initial_ok(tasks,quotas,budgets,caps,n,pairs,dom)
    def query():
        return {'groups':[rnd.randrange(ng) for _ in range(rnd.randint(0,6))],
                'nodes':[rnd.randrange(n) for _ in range(rnd.randint(0,6))],
                'tasks':[rnd.randrange(len(tasks)) for _ in range(rnd.randint(0,min(6,len(tasks))))] if tasks else []}
    initial_query=query()
    return top,n,pairs,dom,ng,caps,groups,tasks,initial_query

def eval_tx(state, tx):
    top,n,pairs,dom,ng,caps,groups,tasks=state
    quotas=[x[0] for x in groups];budgets=[x[1] for x in groups]
    q=tx['query']
    if tx['revision']!=state[9]:
        return {'accepted':False,'revision':state[9],'violations':None,
                'certificate':cert(tasks,quotas,budgets,caps,n,pairs,dom,q)}, False
    rev=state[9]
    start_tasks=[t[:] for t in tasks];start_q=quotas[:];start_b=budgets[:];start_caps=caps[:]
    tup={};qu={};bu={};ca={}
    for e in tx['edits']:
        op,i,v=e
        if op in ('move','weight','class','bind','pin'):
            if i not in tup:tup[i]=tasks[i][:]
            if op=='move':tup[i][1]=v
            elif op=='weight':tup[i][2]=v
            elif op=='class':tup[i][3]=v
            elif op=='bind':tup[i][0]=v
            else:tup[i][4]=v
        elif op=='quota':qu[i]=v
        elif op=='budget':bu[i]=v
        else:ca[i]=v
    qt=quotas[:];bt=budgets[:];ct=caps[:]
    for g,v in qu.items():qt[g]=v
    for g,v in bu.items():bt[g]=v
    for nd,v in ca.items():ct[nd]=v
    nt=tasks[:]
    for i,t in tup.items():nt[i]=t[:]
    gl,gp,gc,gpin,pairsets,usage=stats(nt,qt,bt,ct,n,pairs,dom)
    capv=sum(1 for i in range(n) if usage[i]>ct[i])
    mixv=sum(1 for g in range(ng) if len(pairsets[g])>1)
    workv=sum(1 for g in range(ng) if gc[g] and (qt[g]==0 or gl[g]>qt[g]*bt[g]))
    qchg={g for g,v in qu.items() if v!=quotas[g]}
    pinv=0
    for i,old in enumerate(tasks):
        if not old[4]:continue
        new=nt[i]
        fields=(old[1]!=new[1] or old[0]!=new[0] or old[2]!=new[2] or old[3]!=new[3])
        if fields or old[1] in qchg:pinv+=1
    viol=[capv,mixv,workv,pinv]
    if all(v==0 for v in viol):
        state[5]=ct;state[6]=[[qt[g],bt[g]] for g in range(ng)];state[7]=nt;state[9]=rev+1
        return {'accepted':True,'revision':state[9],'violations':viol,
                'certificate':cert(nt,qt,bt,ct,n,pairs,dom,q)}, True
    else:
        return {'accepted':False,'revision':rev,'violations':viol,
                'certificate':cert(tasks,quotas,budgets,caps,n,pairs,dom,q)}, False

def one(seed):
    top,n,pairs,dom,ng,caps,groups,tasks,startq=gen_seed(seed)
    rnd=random.Random(seed*1000003+7)
    state=[top,n,pairs,dom,ng,caps,groups,tasks,startq,0]
    txs=[]
    for ti in range(rnd.randint(1,50)):
        rev=state[9]
        if rnd.random()<0.2:
            choices=[x for x in (rev-1,rev+1,rev+2,rnd.randint(0,8)) if x>=0 and x!=rev]
            r=rnd.choice(choices)
        else:r=rev
        edits=[]
        for _ in range(rnd.randint(0,10)):
            op=rnd.choice(['move','weight','class','bind','pin','quota','budget','cap'])
            if op in ('move','weight','class','bind','pin'):
                if not tasks:continue
                i=rnd.randrange(len(tasks))
                if op=='move':v=rnd.randrange(ng)
                elif op=='weight':v=rnd.randint(1,20)
                elif op=='class':v=rnd.randint(0,7)
                elif op=='bind':v=rnd.randrange(len(pairs))
                else:v=rnd.randint(0,1)
            elif op in ('quota','budget'):
                i=rnd.randrange(ng);v=rnd.randint(0,5) if op=='quota' else rnd.randint(1,30)
            else:
                i=rnd.randrange(n);v=rnd.randint(0,30)
            edits.append([op,i,v])
        q={'groups':[rnd.randrange(ng) for _ in range(rnd.randint(0,8))],
           'nodes':[rnd.randrange(n) for _ in range(rnd.randint(0,8))],
           'tasks':[rnd.randrange(len(tasks)) for _ in range(rnd.randint(0,min(8,len(tasks))))] if tasks else []}
        tx={'revision':r,'edits':edits,'query':q};txs.append(tx)
    sess={'topology':top,'caps':caps,'groups':groups,'tasks':tasks,'query':startq,'transactions':txs}
    initial=cert(tasks,[x[0] for x in groups],[x[1] for x in groups],caps,n,pairs,dom,startq)
    expected_txs=[]
    for tx in txs:
        res,_=eval_tx(state,tx);expected_txs.append(res)
    exp={'sessions':[{'nodes':n,'templates':len(pairs),'initial':initial,'transactions':expected_txs}]}
    return {'version':2,'sessions':[sess]},exp

def run(seed):
    req,exp=one(seed)
    try:data=entry.transport(req)
    except Exception as e:
        print('TRANSPORT FAIL',seed,e);return False
    p=subprocess.run(['/workspace/tmp/unit-merge-build/engine'],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
