            elif isinstance(a,list):
                if len(a)!=len(b):print('len',path,len(a),len(b));return True
                for i,(x,y) in enumerate(zip(a,b)):
                    if diff(x,y,path+'/'+str(i)):return True
            elif a!=b:print('val',path,a,b);return True
            return False
        diff(got,exp)
        open('/workspace/tmp/all_lastreq.json','w').write(json.dumps(req))
        open('/workspace/tmp/all_lastgot.json','w').write(json.dumps(got))
        open('/workspace/tmp/all_lastexp.json','w').write(json.dumps(exp))
        return False
    return True

